layer.css:
@import url("https://fonts.googleapis.com/css?family=Open+Sans:300italic,400italic,600italic,700italic,400,600,700,300&subset=latin,cyrillic-ext,latin-ext,cyrillic");
[data-ryt="footer"] { color: rgb(211, 211, 211); background-color: rgb(48, 48, 48); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 1px dotted rgb(48, 48, 48); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: var(--ryt-bg); background-color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 600; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s ease-in-out }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { background-image: initial; background-color: rgb(252, 245, 245); color: var(--ryt-accent) }
[data-ryt="credit"]::before, [data-ryt="eyebrow"]::before { content: "/ "; display: inline; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
[data-ryt="nav"] a:hover { color: var(--ryt-text) }
[data-ryt="brand"]:hover { background-image: initial; background-color: rgb(48, 48, 48) }
